from collections import Counter, deque, defaultdict

def transform(grid):
    R, C = len(grid), len(grid[0])
    cnt = Counter(v for row in grid for v in row)
    bg = max(cnt, key=lambda k: cnt[k])
    seen = [[False]*C for _ in range(R)]
    objs = []
    for i in range(R):
        for j in range(C):
            if grid[i][j] != bg and not seen[i][j]:
                col = grid[i][j]
                q = deque([(i, j)]); seen[i][j] = True; cells = []
                while q:
                    x, y = q.popleft(); cells.append((x, y))
                    for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx, ny = x+dx, y+dy
                        if 0 <= nx < R and 0 <= ny < C and not seen[nx][ny] and grid[nx][ny] == col:
                            seen[nx][ny] = True; q.append((nx, ny))
                objs.append({'color': col, 'cells': cells})

    def canon(cells):
        best = None
        tfs = [lambda p: p, lambda p: (p[1], p[0]), lambda p: (p[0], -p[1]), lambda p: (-p[1], p[0]),
               lambda p: (-p[0], p[1]), lambda p: (p[1], -p[0]), lambda p: (-p[0], -p[1]), lambda p: (-p[1], -p[0])]
        for tf in tfs:
            tp = sorted(tf(p) for p in cells)
            x0, y0 = tp[0]
            norm = tuple((x - x0, y - y0) for x, y in tp)
            if best is None or norm < best:
                best = norm
        return best

    groups = defaultdict(list)
    for o in objs:
        groups[canon(o['cells'])].append(o)
    pairs = [v for v in groups.values() if len(v) == 2]
    out = [row[:] for row in grid]
    if not pairs:
        return out

    colorcount = Counter(o['color'] for o in objs)
    singles = [o for o in objs if colorcount[o['color']] == 1]
    needle = max(singles, key=lambda o: len(o['cells'])) if singles else None

    def md(a, b):
        return min(abs(x1-x2) + abs(y1-y2) for x1, y1 in a['cells'] for x2, y2 in b['cells'])

    if len(pairs) == 1:
        pair = pairs[0]
    else:
        diff = [p for p in pairs if p[0]['color'] != p[1]['color']]
        cand = diff if diff else pairs
        if needle:
            pair = max(cand, key=lambda p: abs(md(p[0], needle) - md(p[1], needle)))
        else:
            pair = cand[0]

    if needle:
        a, b = pair
        far = a if md(a, needle) > md(b, needle) else b
        for x, y in far['cells']:
            out[x][y] = needle['color']
    return out
