from collections import Counter, defaultdict, deque

def transform(grid):
    R, C = len(grid), len(grid[0])
    cnt = Counter(v for row in grid for v in row)
    bg = max(cnt, key=lambda k: cnt[k])
    seen = [[False]*C for _ in range(R)]
    objs = []
    for i in range(R):
        for j in range(C):
            if grid[i][j] != bg and not seen[i][j]:
                col = grid[i][j]
                q = deque([(i, j)]); seen[i][j] = True; cells = []
                while q:
                    x, y = q.popleft(); cells.append((x, y))
                    for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx, ny = x+dx, y+dy
                        if 0 <= nx < R and 0 <= ny < C and not seen[nx][ny] and grid[nx][ny] == col:
                            seen[nx][ny] = True; q.append((nx, ny))
                objs.append({'color': col, 'cells': cells})

    def canon(cells, transforms):
        best = None
        for tf in transforms:
            pts = sorted(tf(p) for p in cells)
            x0, y0 = pts[0]
            n = tuple((x-x0, y-y0) for x, y in pts)
            if best is None or n < best:
                best = n
        return best

    idt = [lambda p: p]
    rots = [lambda p: p, lambda p: (p[1], -p[0]),
            lambda p: (-p[0], -p[1]), lambda p: (-p[1], p[0])]

    bycolor = defaultdict(list)
    for o in objs:
        bycolor[o['color']].append(o)
    singles = [v[0] for v in bycolor.values() if len(v) == 1]
    if not singles:
        return [r[:] for r in grid]
    needle = max(singles, key=lambda o: len(o['cells']))

    br0 = min(x for x, y in needle['cells']); br1 = max(x for x, y in needle['cells'])
    bc0 = min(y for x, y in needle['cells']); bc1 = max(y for x, y in needle['cells'])

    def md(o):
        return min(abs(x-nx) + abs(y-ny) for x, y in o['cells'] for nx, ny in needle['cells'])

    def inbbox(o):
        xs = [x for x, y in o['cells']]; ys = [y for x, y in o['cells']]
        return br0 <= min(xs) and max(xs) <= br1 and bc0 <= min(ys) and max(ys) <= bc1

    def find_pairs(rot):
        groups = defaultdict(list)
        for o in objs:
            if o is needle:
                continue
            groups[canon(o['cells'], rots if rot else idt)].append(o)
        return [v for v in groups.values() if len(v) == 2]

    pairs = find_pairs(False)
    if not pairs:
        pairs = find_pairs(True)
    if not pairs:
        return [r[:] for r in grid]

    diff = [p for p in pairs if p[0]['color'] != p[1]['color']]
    if diff:
        pair = max(diff, key=lambda p: abs(md(p[0]) - md(p[1])))
        a, b = pair
        ia, ib = inbbox(a), inbbox(b)
        if ia != ib:
            target = b if ia else a
        else:
            target = a if md(a) < md(b) else b
    else:
        best = None
        for a, b in pairs:
            t = a if md(a) < md(b) else b
            d = md(t)
            if best is None or d < best[0]:
                best = (d, t)
        target = best[1]

    out = [r[:] for r in grid]
    for x, y in target['cells']:
        out[x][y] = needle['color']
    return out
