from collections import Counter, deque

def transform(grid):
    R, C = len(grid), len(grid[0])
    cnt = Counter(v for row in grid for v in row)
    bg = cnt.most_common(1)[0][0]
    seen = [[False]*C for _ in range(R)]
    objs = []
    for i in range(R):
        for j in range(C):
            if grid[i][j] != bg and not seen[i][j]:
                col = grid[i][j]
                q = deque([(i, j)]); seen[i][j] = True; cells = []
                while q:
                    x, y = q.popleft(); cells.append((x, y))
                    for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx, ny = x+dx, y+dy
                        if 0 <= nx < R and 0 <= ny < C and not seen[nx][ny] and grid[nx][ny] == col:
                            seen[nx][ny] = True; q.append((nx, ny))
                objs.append({'c': col, 'cells': cells})
    if not objs:
        return [r[:] for r in grid]
    bycol = {}
    for o in objs:
        bycol.setdefault(o['c'], []).append(o)
    single_objs = [v[0] for v in bycol.values() if len(v) == 1]
    pool = single_objs if single_objs else objs
    needle = max(pool, key=lambda o: len(o['cells']))

    def dist(a):
        return min(abs(x1-x2) + abs(y1-y2) for x1, y1 in a['cells'] for x2, y2 in needle['cells'])

    rest = [o for o in objs if o is not needle]

    def bbox(o):
        xs = [x for x, y in o['cells']]; ys = [y for x, y in o['cells']]
        return max(xs)-min(xs)+1, max(ys)-min(ys)+1

    groups = {}
    for o in rest:
        h, w = bbox(o)
        groups.setdefault((min(h, w), max(h, w)), []).append(o)

    target = None
    best = None
    for k, g in groups.items():
        if len(g) < 2:
            continue
        area = k[0]*k[1]
        sparse = [o for o in g if len(o['cells']) < area]
        if sparse:
            t = sparse[0] if len(sparse) == 1 else max(sparse, key=dist)
            keyd = (area, dist(t))
            if best is None or keyd > best[0]:
                best = (keyd, t)
    if best:
        target = best[1]
    if target is None:
        def canon(cells, rots):
            bestc = None
            for r in range(rots):
                if r == 0: pts = cells
                elif r == 1: pts = [(y, -x) for x, y in cells]
                elif r == 2: pts = [(-x, -y) for x, y in cells]
                else: pts = [(-y, x) for x, y in cells]
                pts = sorted(pts)
                x0, y0 = pts[0]
                n = tuple((x-x0, y-y0) for x, y in pts)
                if bestc is None or n < bestc:
                    bestc = n
            return bestc
        for rots in (1, 4):
            g2 = {}
            for o in rest:
                h, w = bbox(o)
                g2.setdefault((canon(o['cells'], rots), (min(h, w), max(h, w))), []).append(o)
            cand = [(bbox(o[0])[0]*bbox(o[0])[1], v) for v in g2.values() if len(v) == 2]
            if cand:
                cand.sort(key=lambda t: -t[0])
                a, b = cand[0][1]
                target = a if dist(a) > dist(b) else b
                break
    out = [r[:] for r in grid]
    if target is not None:
        for x, y in target['cells']:
            out[x][y] = needle['c']
    return out
