from collections import deque

def transform(grid):
    R, C = len(grid), len(grid[0])
    cnt = {}
    for row in grid:
        for v in row:
            cnt[v] = cnt.get(v, 0) + 1
    bg = max(cnt, key=lambda k: cnt[k])
    seen = [[False]*C for _ in range(R)]
    objs = []
    for i in range(R):
        for j in range(C):
            if grid[i][j] != bg and not seen[i][j]:
                col = grid[i][j]
                q = deque([(i, j)]); seen[i][j] = True; cells = []
                while q:
                    x, y = q.popleft(); cells.append((x, y))
                    for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx, ny = x+dx, y+dy
                        if 0 <= nx < R and 0 <= ny < C and not seen[nx][ny] and grid[nx][ny] == col:
                            seen[nx][ny] = True; q.append((nx, ny))
                objs.append({'c': col, 'cells': cells})
    if not objs:
        return [r[:] for r in grid]

    def bbox(o):
        xs = [x for x, y in o['cells']]; ys = [y for x, y in o['cells']]
        return min(xs), min(ys), max(xs), max(ys)

    bycol = {}
    for o in objs:
        bycol.setdefault(o['c'], []).append(o)
    singles = [v[0] for v in bycol.values() if len(v) == 1]
    pool = singles if singles else objs
    needle = max(pool, key=lambda o: len(o['cells']))
    x0, y0, x1, y1 = bbox(needle)
    cellset = set(needle['cells'])
    corner = None
    for (x, y) in needle['cells']:
        r = (x, y+1) in cellset; l = (x, y-1) in cellset
        d = (x+1, y) in cellset; u = (x-1, y) in cellset
        if (r and d) or (r and u) or (l and d) or (l and u):
            corner = (x, y)
            if r and d: qx, qy = (0, x0), (0, y0)        # away = up-left
            elif r and u: qx, qy = (0, x0), (y1+1, C)    # away = down-left
            elif l and d: qx, qy = (x1+1, R), (0, y0)    # away = up-right
            else: qx, qy = (x1+1, R), (y1+1, C)          # away = down-right
            break
    out = [row[:] for row in grid]
    if corner is None:
        return out
    cands = []
    for o in objs:
        if o is needle:
            continue
        a, b, c2, d2 = bbox(o)
        if a >= qx[0] and c2 < qx[1] and b >= qy[0] and d2 < qy[1]:
            cands.append(o)
    if not cands:
        return out
    cx, cy = corner
    def cdist(o):
        return min(abs(x-cx)+abs(y-cy) for x, y in o['cells'])
    target = max(cands, key=lambda o: (len(o['cells']), -cdist(o)))
    for x, y in target['cells']:
        out[x][y] = needle['c']
    return out
